const pesanan = [
  { id: "A1", status: "dikirim" },
  { id: "A2", status: "diproses" },
  { id: "A3", status: "dikirim" },
];
console.log(pesanan.every((p) => p.status === "dikirim"));
console.log(pesanan.some((p) => p.status === "diproses"));
const i = pesanan.findIndex((p) => p.id === "A3");
console.log(i);
pesanan[i].status = "selesai";
console.log(pesanan.findLast((p) => p.status === "dikirim").id);

